            .ul([["Email + mật khẩu (tối thiểu 8 ký tự): chọn \"Đăng ký\" rồi nhập tên hiển thị, email, mật khẩu.", "Email + password (at least 8 characters): choose \"Sign up\", then enter a display name, email and password."], ["Mã gửi qua email: chọn \"Send sign-in code\" và nhập mã 8 chữ số.", "Emailed code: choose \"Send sign-in code\" and enter the 8-digit code."], ["\"Continue with Google\" hoặc \"Continue with Facebook\".", "\"Continue with Google\" or \"Continue with Facebook\"."], ["Quên mật khẩu: nhấn \"Forgot password?\" để nhận email đặt lại.", "Forgot your password: tap \"Forgot password?\" to get a reset email."]]),
