        HelpSection(id: "pay", vi: "Thanh toán", en: "Paying", blocks: [
            .p("banbe không thu hay giữ tiền. Bạn chuyển khoản trực tiếp cho host; banbe chỉ hiển thị thông tin nhận tiền và ghi nhận trạng thái.", "banbe does not collect or hold money. You transfer directly to the host; banbe only shows the payment details and records the status."),
            .ol([["Mở màn hình thanh toán: xem \"Bank\", \"Account number\", \"Account name\" hoặc quét mã \"Scan to pay\".", "Open the payment screen: see \"Bank\", \"Account number\", \"Account name\" or scan the \"Scan to pay\" code."], ["Ghi đúng \"Transfer reference\" (có nút \"Copy\") vào nội dung chuyển khoản.", "Put the exact \"Transfer reference\" (there is a \"Copy\" button) in your transfer note."], ["Sau khi chuyển, nhập \"Transaction ID\" và (tùy chọn) ảnh biên lai, rồi nhấn xác nhận đã chuyển.", "After transferring, enter the \"Transaction ID\" and optionally a receipt image, then confirm you have transferred."], ["Khi bạn xác nhận đã chuyển, đồng hồ 30 phút dừng và ghế được khóa cho đến khi host xác nhận.", "Once you confirm the transfer, the 30-minute clock stops and your seat is locked until the host confirms."]]),
            .h("Các trạng thái", "Statuses"),
            .ul([["Awaiting confirmation: chờ host xác nhận đã nhận tiền (host thường được kỳ vọng phản hồi trong 1 giờ).", "Awaiting confirmation: waiting for the host to confirm receipt (hosts are expected to respond within about 1 hour)."], ["Under review: banbe đang xem xét tranh chấp; ghế vẫn được giữ.", "Under review: banbe is reviewing a dispute; your seat stays held."], ["Paid / Confirmed: đã xác nhận, vé có mã QR.", "Paid / Confirmed: confirmed, your ticket has a QR code."], ["Hold expired, Booking declined, Cancelled: xem mục Hỏi & Đáp để biết bước tiếp theo.", "Hold expired, Booking declined, Cancelled: see the Q&A for what to do next."]]),
            .p("Host chưa xác nhận? Dùng \"Remind the organizer to confirm\" (tối đa 2 lần), rồi \"Message host\" hoặc \"Raise a dispute\".", "Host has not confirmed? Use \"Remind the organizer to confirm\" (max 2 times), then \"Message host\" or \"Raise a dispute\"."),
            .p("Thông tin xuất hóa đơn của bạn nằm ở Account > Payments & Documents > Billing Details.", "Your invoice details are under Account > Payments & Documents > Billing Details."),
