        HelpSection(id: "tickets", vi: "Vé, mã QR, PDF & lịch", en: "Tickets, QR, PDF & calendar", blocks: [
            .ul([["Mỗi người tham dự có mã QR và mã vào cửa riêng; mỗi người xuất trình mã của chính mình ở cửa.", "Each attendee has their own QR and entry code; each person shows their own code at the door."], ["\"Download PDF\" tải từng vé; có thể tick nhiều vé để tải ZIP hoặc \"Download all\".", "\"Download PDF\" saves one ticket; tick several for a ZIP, or \"Download all\"."], ["\"Add to calendar\" tải tệp .ics cho Apple Calendar hoặc ứng dụng khác.", "\"Add to calendar\" downloads an .ics file for Apple Calendar or other apps."], ["\"View Receipt\" xem biên lai/hóa đơn do host tải lên; \"Request Receipt\" nhờ host gửi nếu chưa có.", "\"View Receipt\" opens the receipt/invoice the host uploaded; \"Request Receipt\" asks the host if there is none yet."], ["Vé hiển thị \"Checked in\" sau khi được quét.", "A ticket shows \"Checked in\" once scanned."]]),
            .tip("Mã QR chỉ xuất hiện sau khi host xác nhận thanh toán. Tính năng Apple Wallet chưa được bật.", "The QR appears only after the host confirms payment. Apple Wallet is not switched on yet."),
        ]),
        HelpSection(id: "gift", vi: "Tặng & nhập vé", en: "Gifting & importing tickets", blocks: [
            .ul([["Tặng vé: \"Give a ticket to a friend\" chuyển quyền vào cửa; bạn vẫn là người sở hữu giao dịch và quyền hoàn tiền nếu host hủy. Không áp dụng cho đặt chỗ có tên người tham dự riêng.", "Gifting: \"Give a ticket to a friend\" hands over admission; you still own the transaction and any refund right if the host cancels. Not available for bookings with named attendees."], ["Nhập vé: Account > Tickets & Bookings > \"Import a gift or group ticket\", nhập mã (ATT-… hoặc CLAIM-…) rồi \"Import ticket\".", "Importing: Account > Tickets & Bookings > \"Import a gift or group ticket\", enter the code (ATT-… or CLAIM-…) and tap \"Import ticket\"."], ["Vé đã nhập hiện ở mục \"Imported tickets\" cùng QR và PDF. Sự kiện chưa thanh toán, đã hủy hoặc đã kết thúc sẽ bị từ chối.", "Imported tickets appear under \"Imported tickets\" with QR and PDF. Unpaid, cancelled or ended events are refused."]]),
        ]),
        HelpSection(id: "refund", vi: "Hoàn tiền", en: "Refunds", blocks: [
            .p("banbe không hoàn tiền thay host. Hoàn tiền theo điều khoản host công bố trên trang sự kiện; khi host hủy sự kiện hoặc hủy đặt chỗ của bạn, một yêu cầu hoàn tiền được tạo.", "banbe does not refund on a host's behalf. Refunds follow the terms the host published on the event page; when a host cancels the event or your booking, a refund claim is created."),
            .ol([["Vào Account > Payments & Documents > Refund Accounts, thêm tài khoản nhận (\"+ Add account\") và đặt mặc định.", "Go to Account > Payments & Documents > Refund Accounts, add a receiving account (\"+ Add account\") and set a default."], ["Trong \"My refunds\", chọn \"Choose a refund destination\" cho yêu cầu của bạn.", "In \"My refunds\", use \"Choose a refund destination\" on your claim."], ["Host chuyển tiền và đánh dấu đã gửi. Khi nhận được, nhấn \"Confirm received\".", "The host transfers and marks it sent. When it arrives, tap \"Confirm received\"."], ["Chưa nhận được hoặc có vấn đề: nhấn \"Dispute refund\" / \"Raise a dispute\".", "Not received or something is wrong: tap \"Dispute refund\" / \"Raise a dispute\"."]]),
            .ul([["Hạn hoàn tiền host cam kết là 3 ngày làm việc kể từ lúc hủy.", "The refund deadline the host owes is 3 business days after cancellation."], ["Nếu bạn không phản hồi, hoàn tiền tự động được ghi nhận đã nhận sau 7 ngày kể từ khi host đánh dấu đã gửi. Hãy kiểm tra sớm.", "If you do nothing, the refund is auto-confirmed 7 days after the host marks it sent. Check early."], ["Có thể thêm nhiều tài khoản, sắp xếp lại, ẩn/hiện, sửa, đặt mặc định hoặc xóa.", "You can add several accounts, reorder, hide/reveal, edit, set a default or delete."]]),
        ]),
        HelpSection(id: "dispute", vi: "Khiếu nại & chat khiếu nại", en: "Disputes & dispute chat", blocks: [
            .p("Có hai loại: tranh chấp thanh toán (host báo không thấy tiền) và tranh chấp hoàn tiền (bạn báo chưa nhận được tiền).", "There are two kinds: payment disputes (the host says they cannot find your payment) and refund disputes (you say you did not receive a refund)."),
            .ul([["Khi một tranh chấp được chuyển lên banbe, một khung chat tạm thời mở ra giữa bạn, host và quản trị viên đọc được.", "When a dispute is escalated to banbe, a temporary chat opens between you and the host; admins can read it."], ["Có thể đính kèm ảnh JPG/PNG/WebP hoặc PDF (tối đa 20 MB). Tin nhắn không sửa hoặc xóa được.", "You can attach JPG/PNG/WebP or PDF files (max 20 MB). Messages cannot be edited or deleted."], ["\"Close dispute\" kết thúc tranh chấp. Sau đó có thể \"Download transcript\" và \"Close and delete my copy\" (chỉ ẩn bản của bạn).", "\"Close dispute\" ends it. Afterwards you can \"Download transcript\" and \"Close and delete my copy\" (hides only your copy)."], ["Dữ liệu tranh chấp hoàn tiền được xóa 7 ngày sau khi đóng.", "Refund-dispute data is purged 7 days after it closes."]]),
            .p("Nếu host chỉ bấm \"Can't find it\" mà chưa nâng lên banbe, bạn chỉ nhận tin trong chat thường; hãy phản hồi hoặc gửi thêm bằng chứng.", "If the host only tapped \"Can't find it\" without escalating, you just get a message in your normal chat; reply or send more proof."),
        ]),
        HelpSection(id: "chat", vi: "Tin nhắn & thông báo", en: "Messages & notifications", blocks: [
            .ul([["Tab \"Messages\": các cuộc trò chuyện với host. Cuộc trò chuyện chỉ xuất hiện sau tin nhắn đầu tiên bạn gửi. Menu \"...\" cho phép Star, Archive, Delete (xóa chỉ với bạn).", "The \"Messages\" tab holds your chats with hosts. A chat appears only after you send the first message. The \"...\" menu offers Star, Archive, Delete (removes it for you only)."], ["Gửi ảnh hoặc tài liệu bằng \"Add photo or document\" / \"Camera\".", "Send photos or documents with \"Add photo or document\" / \"Camera\"."], ["Tab \"Notifications\": nhóm New / Today / Last 7 days / Older; đánh dấu đã đọc, tắt loại thông báo, xóa, chọn nhiều.", "The \"Notifications\" tab groups New / Today / Last 7 days / Older; mark read, mute a kind, delete, multi-select."], ["Thông báo trong ứng dụng và email đang hoạt động; thông báo đẩy (push) chưa bật.", "In-app and email notifications work; push notifications are not enabled yet."]]),
        ]),
        HelpSection(id: "survey", vi: "Khảo sát", en: "Surveys", blocks: [
            .p("Host dùng khảo sát để đo nhu cầu. Mở một khảo sát từ Trang chủ hoặc story, điền mức quan tâm, thời gian/địa điểm ưa thích, quy mô nhóm, ngân sách…, tick đồng ý để host liên hệ về sự kiện đó, rồi \"Submit response\".", "Hosts use surveys to gauge demand. Open one from Home or a story, fill in interest, preferred time/place, group size, budget…, tick consent for the host to contact you about that event, then \"Submit response\"."),
            .ul([["Trả lời khảo sát không giữ chỗ cho bạn.", "Answering a survey does not reserve a place."], ["Có thể chỉnh sửa câu trả lời đến khi khảo sát đóng (\"Edit Response\").", "You can edit your answer until the survey closes (\"Edit Response\")."], ["Nếu chưa đăng nhập, bạn xác minh email bằng mã 8 chữ số.", "If you are not signed in, verify your email with an 8-digit code."]]),
        ]),
        HelpSection(id: "profile", vi: "Hồ sơ, thẻ chia sẻ & mời bạn bè", en: "Profile, share card & inviting friends", blocks: [
            .ul([["Account > \"Personal Profile\": đổi ảnh, handle, tên hiển thị, giới thiệu, thành phố, sở thích, bảng màu.", "Account > \"Personal Profile\": change photo, handle, display name, bio, city, interests, palette."], ["Trang công khai của bạn ở /u/<handle> ai có link cũng xem được.", "Your public page lives at /u/<handle> and anyone with the link can view it."], ["Thẻ chia sẻ: chọn màu, nền, \"Save card\", \"Download image\", \"Copy link\", \"Share…\".", "Share card: pick colours and background, then \"Save card\", \"Download image\", \"Copy link\", \"Share…\"."], ["\"Invite friends\" tạo link mời cá nhân.", "\"Invite friends\" creates your personal invite link."], ["Trang hồ sơ của bạn có một hàng ba nút nhỏ: \"QR code\" (hiện mã QR), \"Edit profile\" (sửa hồ sơ) và \"Edit charm\" (sửa móc khoá). Người khác xem hồ sơ của bạn chỉ thấy nút QR.", "Your own profile page has one row of three small buttons: \"QR code\" (show the QR), \"Edit profile\" and \"Edit charm\" (edit your keychain). Visitors only see the QR button."], ["\"Post a story\": ảnh + văn bản + link, tự hết hạn sau 24 giờ.", "\"Post a story\": photo + text + link, expires after 24 hours."]]),
        ]),
        HelpSection(id: "keychain", vi: "Móc khoá trang trí hồ sơ", en: "Profile keychain charm", blocks: [
            .p("Móc khoá là một món trang trí nhỏ treo ở góc thẻ hồ sơ. Mặc định tắt; khi bật, người xem hồ sơ của bạn cũng thấy nó.", "The keychain is a small decoration hanging from a corner of your profile card. It is off by default; when on, people who view your profile see it too."),
            .h("Bật và chỉnh móc khoá", "Turn it on and customise it"),
            .ol([["Mở hồ sơ của bạn rồi nhấn \"Edit charm\", hoặc vào Edit profile > Keychain.", "Open your profile and tap \"Edit charm\", or go to Edit profile > Keychain."], ["Bật công tắc, chọn một trong 24 mẫu (nhóm sao/trăng/mây, tim/nơ, hoa/trái cây, cà phê/âm nhạc, mèo/gấu, du lịch/vé, họa tiết banbe).", "Switch it on and pick one of 24 designs (stars/moon/clouds, hearts/ribbons, flowers/fruits, coffee/music, cats/bears, travel/tickets, banbe motifs)."], ["Chọn một trong bốn góc, kích cỡ S/M/L và bật/tắt chuyển động. Xem trước ngay trong màn hình rồi nhấn Save; Cancel sẽ bỏ thay đổi.", "Choose one of four corners, size S/M/L and motion on/off. Preview it on the screen, then tap Save; Cancel discards changes."]]),
            .h("Tải ảnh mẫu & dùng ảnh riêng", "Export artwork & use your own"),
            .ul([["\"Download artwork\" / nút chia sẻ lưu ảnh PNG của mẫu đang chọn.", "\"Download artwork\" / the share button saves the PNG of the selected design."], ["\"Use my own art\": chọn tệp PNG hoặc WebP nền trong suốt bạn đã tải ở nơi khác (tối đa 512 px, 256 KB; ảnh được thu nhỏ trên máy và xoá siêu dữ liệu như vị trí). SVG, HTML và GIF không được chấp nhận. Mỗi tài khoản giữ tối đa 3 ảnh; \"Remove my art\" để xoá ảnh của bạn.", "\"Use my own art\": pick a transparent PNG or WebP you downloaded elsewhere (up to 512 px, 256 KB; it is resized on your device and metadata such as location is removed). SVG, HTML and GIF are not accepted. Each account keeps at most 3 images; \"Remove my art\" deletes yours."], ["Ảnh riêng chỉ được người dùng đăng nhập khác xem khi móc khoá của bạn đang bật. Hãy chỉ dùng ảnh bạn có quyền sử dụng.", "Your own art can be seen by other signed-in users only while your keychain is on. Only use images you have the right to use."]]),
            .h("Chơi với móc khoá", "Playing with it"),
            .ul([["Kéo móc khoá lên/xuống để kéo giãn, thả ra để nó đung đưa rồi dừng. Cuộn trang bình thường ở những chỗ khác.", "Drag the charm up or down to stretch it, release and it swings then settles. Scroll the page as usual anywhere else."], ["Trên iPhone, móc khoá nhẹ nhàng phản ứng khi bạn nghiêng hoặc lắc máy và rung nhẹ khi chạm/thả (theo cài đặt Haptic của app). Trên web, nhấn \"Enable tilt\" trong màn hình Keychain để cho phép cảm biến (cần HTTPS và sự đồng ý của bạn).", "On iPhone the charm gently responds to tilting or shaking and gives a light tap on grab/release (following the app Haptic setting). On the web, tap \"Enable tilt\" on the Keychain screen to allow the sensor (needs HTTPS and your permission)."], ["Không muốn kéo? Dùng nút \"Swing\" hoặc, trên web, chọn móc khoá rồi nhấn Enter/Space. Khi bật \"Giảm chuyển động\" hoặc tắt chuyển động, móc khoá đứng yên.", "Prefer not to drag? Use the \"Swing\" button or, on the web, focus the charm and press Enter/Space. With Reduce Motion on or motion off, the charm stays still."]]),
        ]),
        HelpSection(id: "settings", vi: "Cài đặt, bảo mật & xóa tài khoản", en: "Settings, security & deleting your account", blocks: [
            .ul([["Account > Settings: ngôn ngữ (Tiếng Việt / English) và giao diện (Light / Dark). Ngôn ngữ cũng áp dụng cho tin nhắn tự động.", "Account > Settings: language (Vietnamese / English) and appearance (Light / Dark). Language also applies to automated messages."], ["\"Security\": đổi mật khẩu (8+ ký tự) và xem trạng thái xác minh điện thoại.", "\"Security\": change your password (8+ characters) and see your phone-verification status."], ["Có tùy chọn tự động email bản sao hóa đơn/biên lai cho bạn.", "There is an option to automatically email you copies of invoices/receipts."], ["Đăng xuất bằng \"Sign out\" trong Account.", "Log out with \"Sign out\" in Account."]]),
            .h("Xóa tài khoản", "Deleting your account"),
            .ol([["Account > Settings > \"Delete Account\" > Continue.", "Account > Settings > \"Delete Account\" > Continue."], ["Xác minh bằng mã 8 chữ số gửi qua email.", "Verify with the 8-digit code emailed to you."], ["Gõ đúng cụm từ xác nhận và nhấn \"Permanently delete account\".", "Type the exact confirmation phrase and tap \"Permanently delete account\"."]]),
            .tip("Không thể hoàn tác. Bạn không xóa được khi còn sở hữu sự kiện đang mở; hãy hủy hoặc kết thúc sự kiện trước. Yêu cầu bản sao dữ liệu: liên hệ email nêu trong Điều khoản.", "This cannot be undone. You cannot delete while you still own an open event; cancel or end it first. To request a copy of your data, use the contact email in the Terms."),
        ]),
        HelpSection(id: "search", vi: "Tìm kiếm trong Tài khoản", en: "Searching inside Account", blocks: [
            .p("Ô \"Search Account…\" trên màn hình Account tìm mọi mục (cài đặt, vé, hoàn tiền, trợ giúp…) và mở thẳng tới đó.", "The \"Search Account…\" box on the Account screen finds any entry (settings, tickets, refunds, help…) and jumps straight to it."),
        ]),
        ]
    )

    static let host = HelpDoc(
        vi: "Hướng dẫn cho Host (Người tổ chức)", en: "Guide for Hosts",
        introVi: "Từ bật chế độ tổ chức, tạo sự kiện, nhận thanh toán, soát vé đến hủy sự kiện, hoàn tiền và xử lý tranh chấp.", introEn: "From turning on organizer mode and creating events to getting paid, checking guests in, cancelling, refunds and disputes.",
        adminOnly: false,
        sections: [
        HelpSection(id: "start", vi: "Trở thành host", en: "Becoming a host", blocks: [
            .ol([["Vào Account, bật công tắc \"Organizer mode\" (tab Host xuất hiện; tắt bất cứ lúc nào).", "Go to Account and switch on \"Organizer mode\" (the Host tab appears; turn it off any time)."], ["Ngay khi bật chế độ tổ chức, banbe tự tạo trang tổ chức cho bạn với tên mặc định \"<tên hiển thị> Events\" (hoặc \"Sự kiện của tôi\" nếu chưa có tên). Bạn có thể đổi tên bất cứ lúc nào; tên không lấy từ email hay số điện thoại và không có nghĩa là đã được xác minh. Nếu thẻ Host báo lỗi, nhấn \"Retry\". Thành viên nhóm của tổ chức khác không bị tạo thêm trang.", "As soon as you switch on organizer mode, banbe creates your organizer page with a default name \"<display name> Events\" (or \"My events\" if you have no name). You can rename it any time; the name is never taken from your email or phone and does not mean you are verified. If the Host card shows an error, tap \"Retry\". Members of another organizer's team do not get a second page created."], ["Điền phần giới thiệu trang tổ chức của bạn khi tạo sự kiện đầu tiên (hoặc sửa tên/giới thiệu ở hồ sơ công khai của tổ chức).", "Fill in your organizer about text when you create your first event (or edit the name/about on your organizer public profile)."], ["Chính sách yêu cầu host từ 18 tuổi trở lên.", "The Terms require hosts to be 18 or older."]]),
            .p("banbe hiện miễn phí cho host: không phí niêm yết hay phí giao dịch. Mọi sự kiện mới đều được quản trị viên banbe duyệt trước khi công khai.", "banbe is currently free for hosts: no listing or transaction fees. Every new event is reviewed by a banbe admin before it goes public."),
        ]),
        HelpSection(id: "create", vi: "Tạo sự kiện", en: "Creating an event", blocks: [
            .p("Nhấn nút tạo sự kiện (dấu +) và điền các mục sau.", "Tap the create (+) button and fill in the following."),
            .ul([["Tên, mô tả (bắt buộc) và \"Event introduction\" (phần giới thiệu dài).", "Name, description (required) and \"Event introduction\" (longer write-up)."], ["Địa điểm: gõ rồi chọn một địa chỉ gợi ý; bắt buộc trước khi gửi.", "Location: type and pick a suggested address; required before submitting."], ["Ngày, giờ, giá vé và số chỗ (lớn hơn 0).", "Date, time, ticket price and seats (more than 0)."], ["Riêng tư: Public hoặc Invite-only (chỉ người được mời xem và đặt; vẫn cần banbe duyệt).", "Privacy: Public or Invite-only (only invited people can see and book; still needs banbe approval)."], ["Danh mục (1–2) và từ khóa tìm kiếm (tùy chọn).", "Category (1–2) and search keywords (optional)."], ["Ảnh: JPEG/PNG/WebP, mỗi ảnh dưới 50 MB, tối đa 8 ảnh; đặt ảnh bìa và sắp xếp.", "Photos: JPEG/PNG/WebP, each under 50 MB, up to 8; set a cover and reorder."], ["\"Included\": tối đa 3 mục, cần ít nhất 1.", "\"Included\": up to 3 items, at least 1 required."], ["\"Opening message\": lời chào đầu tiên khách thấy khi nhắn cho bạn (tiếng Việt và English, mỗi bản tối đa 500 ký tự; để trống sẽ dùng lời chào mặc định).", "\"Opening message\": the first message guests see when they chat with you (Vietnamese and English, 500 characters each; blank uses a default greeting)."]]),
            .p("Ghi rõ giá và điều khoản hoàn tiền trên trang sự kiện; đó là trách nhiệm của host.", "State the price and refund terms on the event page; that is the host's responsibility."),
            .p("Bước \"Review before submitting\" có tab Private (Host) và Public preview. Nhấn \"Confirm & submit\" để gửi duyệt.", "The \"Review before submitting\" step has Private (Host) and Public preview tabs. Tap \"Confirm & submit\" to send it for review."),
            .h("Nhập từ Excel", "Importing from Excel"),
            .p("Chọn \"Upload a completed file\" (.xlsx hoặc .zip có ảnh). Tệp chỉ điền sẵn biểu mẫu (một sự kiện mỗi tệp); bạn xem lại và gửi như bình thường. Tệp sai sẽ hiện danh sách lỗi từng trường.", "Choose \"Upload a completed file\" (.xlsx, or a .zip with photos). The file only pre-fills the form (one event per file); you review and submit as usual. A wrong file shows a field-by-field error list."),
        ]),
        HelpSection(id: "review", vi: "Chờ duyệt, chỉnh sửa & rút lại", en: "Review, fixes & withdrawing", blocks: [
            .ul([["\"Submitted events\" trên Dashboard/Account cho thấy \"Waiting for Banbe to review\" hoặc \"Needs fixing\".", "\"Submitted events\" shows \"Waiting for Banbe to review\" or \"Needs fixing\"."], ["Bị từ chối: đọc lý do rồi \"Fix & resubmit\".", "Rejected: read the reason, then \"Fix & resubmit\"."], ["Chờ lâu: gửi nhắc quản trị viên (tối đa 2 lần mỗi sự kiện).", "Waiting a long time: remind the admins (max 2 times per event)."], ["\"Withdraw event\" rút lại sự kiện đang chờ duyệt (kèm lý do).", "\"Withdraw event\" pulls back a pending event (with a reason)."]]),
            .tip("Thời gian duyệt không được cam kết; hãy gửi sớm trước ngày diễn ra.", "Review time is not guaranteed; submit well before the event date."),
        ]),
        HelpSection(id: "payout", vi: "Nhận thanh toán & tài liệu", en: "Getting paid & documents", blocks: [
            .p("banbe không giữ tiền: khách chuyển thẳng cho bạn.", "banbe does not hold money: guests pay you directly."),
            .ol([["Account > Event Operations & Payments > \"Getting Paid\": nhập Bank, tên ngân hàng, số tài khoản, tên chủ tài khoản hoặc MoMo.", "Account > Event Operations & Payments > \"Getting Paid\": enter Bank, bank name, account number, account name, or MoMo."], ["Thêm địa chỉ, mã số thuế (tùy chọn) và \"Note to guests\".", "Add an address, tax code (optional) and a \"Note to guests\"."], ["Có thể tải một mã QR thanh toán (mỗi tổ chức một mã) để khách quét.", "You can upload one payment QR (one per organizer) for guests to scan."]]),
            .h("Hóa đơn / biên lai", "Invoices / receipts"),
            .p("Trong \"Attendance\", sau khi thấy tiền về, đánh dấu khách đã trả rồi \"Upload receipt\" (tệp của chính bạn). \"Replace receipt\" cần lý do khách sẽ thấy; bản cũ tự xóa sau 24 giờ. Tài liệu được lưu 12 tháng.", "In \"Attendance\", once you see the money, mark the guest paid and \"Upload receipt\" (your own file). \"Replace receipt\" needs a reason the guest will see; the old copy is deleted after 24 hours. Documents are kept 12 months."),
        ]),
        HelpSection(id: "confirm", vi: "Xác nhận thanh toán của khách", en: "Confirming guest payments", blocks: [
            .p("Vào Account > Event Operations & Payments > \"Awaiting Verification\". Mỗi dòng cho thấy khách, số vé, Reference, Transaction ID và ảnh biên lai.", "Go to Account > Event Operations & Payments > \"Awaiting Verification\". Each row shows the guest, ticket count, Reference, Transaction ID and receipt image."),
            .ul([["\"Money received\": xác nhận và cấp vé QR cho khách.", "\"Money received\": confirms and issues the guest's QR ticket."], ["\"Can't find it\": báo không thấy tiền; khách nhận tin trong chat thường.", "\"Can't find it\": says you cannot see the money; the guest gets a message in the normal chat."], ["\"Escalate to banbe\": nhờ quản trị viên quyết định, mở chat tranh chấp tạm thời.", "\"Escalate to banbe\": asks admins to decide and opens a temporary dispute chat."], ["Sự kiện cần duyệt khách: \"Accept\" hoặc \"Reject\" yêu cầu; \"Cancel booking\" trả chỗ về và thông báo cho khách.", "Approval-required events: \"Accept\" or \"Reject\" requests; \"Cancel booking\" frees the seat and notifies the guest."]]),
            .tip("Bạn nên phản hồi trong khoảng 1 giờ. banbe KHÔNG tự xác nhận thay bạn: ghế của khách bị khóa cho tới khi bạn hành động. Quá hạn sẽ có nhắc nhở và leo thang.", "Aim to respond within about 1 hour. banbe does NOT auto-confirm for you: the guest's seat stays locked until you act. Overdue items trigger reminders and escalation."),
        ]),
        HelpSection(id: "checkin", vi: "Soát vé & danh sách khách", en: "Check-in & the guest list", blocks: [
            .ol([["Từ Dashboard, mở sự kiện > \"Check-in\" (Guest check-in).", "From the Dashboard, open the event > \"Check-in\" (Guest check-in)."], ["\"Scan QR\" (cho phép trình duyệt dùng camera) và quét mã của từng người; kiểm tra tuổi/ngày sinh hiển thị rồi \"Confirm\".", "\"Scan QR\" (allow camera access) and scan each person's code; check the age/date of birth shown, then \"Confirm\"."], ["Hoặc chạm \"Here ✓\" / \"Not yet\" thủ công; \"Undo check-in\" để hoàn tác.", "Or tap \"Here ✓\" / \"Not yet\" manually; \"Undo check-in\" reverts it."]]),
            .ul([["Mỗi QR chỉ cho vào đúng một người; QR của cả đơn đặt chỗ bị từ chối (\"Scan each attendee's own QR\").", "Each QR admits one person only; a whole-booking QR is refused (\"Scan each attendee's own QR\")."], ["Lỗi thường gặp: mã không hợp lệ, đã check-in, mã đã bị thay do tặng vé, quét quá nhiều lần.", "Common errors: invalid code, already checked in, code replaced because the ticket was gifted, too many attempts."], ["\"Email ticket holders\" gửi thông báo cho người giữ vé.", "\"Email ticket holders\" sends a message to ticket holders."]]),
        ]),
        HelpSection(id: "cancel", vi: "Hủy sự kiện & email xin lỗi", en: "Cancelling an event & apology emails", blocks: [
            .ol([["Attendance > \"Cancel event\".", "Attendance > \"Cancel event\"."], ["Chọn một mẫu lời xin lỗi (ngoài ý muốn, địa điểm, ít người đăng ký, an toàn), xem trước rồi xác nhận. Tất cả đặt chỗ bị hủy và các yêu cầu hoàn tiền được tạo.", "Pick an apology template (unforeseen, venue, low sign-ups, safety), preview, then confirm. All bookings are cancelled and refund claims are created."], ["Mỗi người giữ vé có một bản nháp email cá nhân hóa mở trong ứng dụng email CỦA BẠN; banbe không tự gửi.", "Each ticket holder gets a personalised draft that opens in YOUR mail app; banbe does not send it."]]),
        ]),
        HelpSection(id: "refunds", vi: "Hoàn tiền cho khách", en: "Refunding guests", blocks: [
            .ol([["Chờ khách chọn tài khoản nhận (chỉ khi đó khoản hoàn mới đủ điều kiện).", "Wait for the guest to choose a destination (only then is the claim eligible)."], ["Mở Refund Center, chuyển khoản theo thông tin khách chọn.", "Open the Refund Center and transfer using the guest's chosen details."], ["Chọn các khoản rồi \"Confirm transfers sent\" (hàng loạt) hoặc \"Mark refund sent\" từng khoản; có thể thêm ghi chú và chứng từ chuyển khoản.", "Select claims and use \"Confirm transfers sent\" (batch) or \"Mark refund sent\" per claim; add a note and transfer proof if you like."]]),
            .ul([["Hạn hoàn tiền là 3 ngày làm việc kể từ lúc hủy.", "The refund is due 3 business days after cancellation."], ["Khách có 7 ngày để xác nhận; nếu không phản hồi, hệ thống tự ghi nhận đã nhận.", "Guests have 7 days to confirm; if they do nothing it is auto-confirmed."], ["Khách báo chưa nhận: \"Resend transfer info\". Bạn có 48 giờ phản hồi khi có tranh chấp hoàn tiền.", "Guest says it did not arrive: \"Resend transfer info\". You have 48 hours to respond to a refund dispute."]]),
        ]),
        HelpSection(id: "disputes", vi: "Tranh chấp", en: "Disputes", blocks: [
            .ul([["Tranh chấp thanh toán: \"Escalate to banbe\" kèm mô tả; quản trị viên đọc chat và bằng chứng rồi quyết định (\"Buyer is right\" cấp vé, hoặc \"Release seat\").", "Payment dispute: \"Escalate to banbe\" with a description; admins read the chat and proof, then decide (\"Buyer is right\" issues the ticket, or \"Release seat\")."], ["Tranh chấp hoàn tiền: mở \"Open dispute chat\" từ hộp thư (dòng \"Dispute in progress\"); đính kèm tệp; \"Close dispute\" khi xong.", "Refund dispute: open \"Open dispute chat\" from the inbox (\"Dispute in progress\" row); attach files; \"Close dispute\" when done."], ["Có thể tải transcript; bản của host được giữ đến khi dữ liệu bị xóa (7 ngày sau khi đóng).", "You can download the transcript; the host copy is kept until the data is purged (7 days after closing)."]]),
        ]),
        HelpSection(id: "invite", vi: "Sự kiện chỉ mời & khảo sát", en: "Invite-only events & surveys", blocks: [
            .ul([["Invite-only: chọn khi tạo sự kiện; chỉ người được mời mới xem và đặt được. Hiện chưa có màn hình quản lý lời mời cho host.", "Invite-only: choose it when creating; only invited people can see and book. There is no host screen to manage invites yet."], ["Khảo sát (Account > Surveys & Event Ideas): \"+ Create a new survey\", rồi \"Publish\", chia sẻ link hoặc story, \"Close early\" / \"Archive\".", "Surveys (Account > Surveys & Event Ideas): \"+ Create a new survey\", then \"Publish\", share the link or a story, \"Close early\" / \"Archive\"."], ["Khi khảo sát đóng, gợi ý sự kiện có thể được tạo; \"Use This Idea\" mở biểu mẫu tạo sự kiện đã điền sẵn.", "When a survey closes, event suggestions may be generated; \"Use This Idea\" opens a pre-filled create form."]]),
        ]),
        HelpSection(id: "team", vi: "Đội ngũ, hồ sơ host & thẻ chia sẻ", en: "Team, host profile & share card", blocks: [
            .ul([["Team: mời thành viên theo @handle với vai trò công khai; trạng thái Pending / Joined / Declined / Removed; có thể ẩn khỏi trang công khai.", "Team: invite members by @handle with a public role; statuses Pending / Joined / Declined / Removed; they can be hidden from the public page."], ["\"Credit an event contribution\" ghi nhận ai đã giúp tổ chức sự kiện (\"Helped organize\" trên hồ sơ họ).", "\"Credit an event contribution\" records who helped organize an event (\"Helped organize\" on their profile)."], ["Hồ sơ host (/org/<id>): theo dõi, sự kiện, ảnh, huy hiệu \"Verified\" do banbe gán thủ công; \"Request\" để xin xác minh.", "Host profile (/org/<id>): followers, events, photos, a \"Verified\" badge set manually by banbe; \"Request\" to ask for verification."], ["Thẻ chia sẻ: chọn màu/nền, \"Save card\" để công bố, tải ảnh hoặc sao chép link.", "Share card: pick colours/background, \"Save card\" to publish, download the image or copy the link."], ["Thành viên team có thể chạy cửa và chat; chỉ chủ hồ sơ mới sửa sự kiện, hủy sự kiện và quản lý thành viên.", "Team members can run the door and chat; only the profile owner edits events, cancels them and manages members."]]),
        ]),
        HelpSection(id: "reports", vi: "Số liệu & báo cáo", en: "Metrics & reports", blocks: [
            .p("Account > \"Metrics & Reports\": số sự kiện đã đăng, chỗ đã xác nhận, đã check-in, số tiền đã xác nhận, hoàn tiền phải trả/quá hạn. Xuất \"Download CSV\", JSON, PDF hoặc \"Save image\".", "Account > \"Metrics & Reports\": published events, confirmed seats, checked in, confirmed payment amount, refunds owed/overdue. Export \"Download CSV\", JSON, PDF or \"Save image\"."),
        ]),
        HelpSection(id: "tips", vi: "Lưu ý quan trọng", en: "Important reminders", blocks: [
            .ul([["Không thể xóa tài khoản khi còn sự kiện đang mở.", "You cannot delete your account while you own an open event."], ["Thời gian giữ chỗ 30 phút không tùy chỉnh được.", "The 30-minute hold cannot be customised."], ["Hãy xác nhận thanh toán nhanh: banbe không tự xác nhận.", "Confirm payments promptly: banbe never confirms automatically."], ["Không chuyển tiền hộ qua banbe; mọi giao dịch diễn ra giữa bạn và khách.", "banbe does not move money; all payments are between you and your guests."]]),
        ]),
        ]
    )

    static let admin = HelpDoc(
        vi: "Hướng dẫn cho Quản trị viên", en: "Admin Guide",
        introVi: "Ngắn gọn, chỉ dành cho quản trị viên. Tab \"Admin\" chỉ hiện với tài khoản có vai trò admin trên máy chủ.", introEn: "Concise and for admins only. The \"Admin\" tab only appears for accounts with the server-side admin role.",
        adminOnly: true,
        sections: [
        HelpSection(id: "overview", vi: "Tổng quan", en: "Overview", blocks: [
            .ul([["Tab \"Admin\" > \"Administration\" gồm: Review & Moderation, Admin Team, Metrics & Reports.", "The \"Admin\" tab > \"Administration\" has: Review & Moderation, Admin Team, Metrics & Reports."], ["Quyền do máy chủ kiểm soát; ứng dụng không thể tự cấp quyền admin.", "Permissions are enforced by the server; the app cannot grant itself admin."], ["Mọi thao tác quản trị được ghi lại.", "Admin actions are logged."]]),
        ]),
        HelpSection(id: "events", vi: "Duyệt sự kiện", en: "Approving events", blocks: [
            .ol([["Review & Moderation > \"Pending Events\" (có huy hiệu số lượng).", "Review & Moderation > \"Pending Events\" (with a count badge)."], ["Mở thẻ sự kiện, kiểm tra mô tả, \"Included\", địa chỉ, riêng tư, loại tổ chức tự khai và thông tin đăng ký kinh doanh (chưa được banbe xác minh).", "Open the event card and check the description, \"Included\", address, visibility, the self-declared organizer type and business details (not verified by banbe)."], ["\"Approve ▪︎ publish\" để đăng, hoặc \"Reject\" kèm lý do bắt buộc.", "\"Approve ▪︎ publish\" to go live, or \"Reject\" with a required reason."]]),
            .tip("Host có thể nhắc tối đa 2 lần mỗi sự kiện; không có hạn chót tự động, nên xử lý theo thứ tự cũ nhất trước.", "Hosts can remind up to 2 times per event; there is no automatic deadline, so work oldest first."),
        ]),
        HelpSection(id: "disputes", vi: "Xử lý tranh chấp", en: "Resolving disputes", blocks: [
            .ol([["Review & Moderation > \"Payment disputes\".", "Review & Moderation > \"Payment disputes\"."], ["Xem khách, Reference, Transaction ID, ảnh biên lai, lý do host từ chối và chat tranh chấp.", "Review the guest, Reference, Transaction ID, receipt image, the host's rejection reason and the dispute chat."], ["Tranh chấp thanh toán: \"Buyer is right ▪︎ issue ticket\" hoặc \"Release seat\"; thêm \"Resolution note\".", "Payment dispute: \"Buyer is right ▪︎ issue ticket\" or \"Release seat\"; add a \"Resolution note\"."], ["Tranh chấp hoàn tiền cũng nằm trong hàng đợi này.", "Refund disputes are in the same queue."]]),
            .p("Sau quyết định, hai bên nhận thông báo và email. Nếu email lỗi, lỗi chỉ hiện trên màn hình của bạn lúc đó.", "After a decision both parties get a notification and email. If the email fails the error shows only on your screen at that moment."),
        ]),
        HelpSection(id: "team", vi: "Đội ngũ quản trị", en: "Admin Team", blocks: [
            .ul([["\"Invite Admin\" gửi lời mời qua email dùng một lần; email người nhận được kiểm tra khi chấp nhận.", "\"Invite Admin\" sends a single-use email invite; the invitee's email is verified when accepting."], ["Quyền quản lý admin là quyền riêng; admin mới không tự có, phải được người đang có quyền cấp.", "Managing admins is a separate permission; a new admin does not get it automatically and must be granted it."], ["Thu hồi admin sẽ hạ về người tham gia; không thể tự thu hồi mình hoặc thu hồi admin cuối cùng.", "Revoking an admin demotes them to a participant; you cannot revoke yourself or the last admin."], ["Người được mời thấy lời mời trong \"Việc cần xử lý\" (Trang chính và Tài khoản) và chấp nhận hoặc từ chối trong Đội ngũ quản trị; lời mời hết hạn sau 7 ngày. Khi họ phản hồi, bạn nhận thông báo và danh sách tự làm mới.", "The invitee sees the invite under \"Things to do\" (Home and Account) and accepts or declines it in Admin Team; invites expire after 7 days. When they answer you get a notification and the list refreshes."]]),
        ]),
        HelpSection(id: "protected", vi: "Tài khoản quản trị được bảo vệ", en: "Protected admin", blocks: [
            .p("Tài khoản banbetestadmin@gmail.com được bảo vệ: không ai có thể bỏ quyền quản lý đội ngũ hay gỡ vai trò quản trị của tài khoản này một cách trực tiếp.", "The banbetestadmin@gmail.com account is protected: nobody can remove its team-management access or its admin role directly."),
            .ul([["Khi chỉ có dưới 3 quản trị viên (tính cả tài khoản này), việc gỡ bị chặn hoàn toàn.", "With fewer than 3 admins in total (counting this account), removal is blocked outright."], ["Từ 3 quản trị viên trở lên, một quản trị viên có quyền quản lý đội ngũ có thể mở cuộc bỏ phiếu: \"Start a vote: remove team-management access\" hoặc \"Start a vote: remove as admin\" ở dòng của tài khoản đó trong Current Admins.", "With 3 or more admins, an admin who has team-management access can open a vote: \"Start a vote: remove team-management access\" or \"Start a vote: remove as admin\" on that account's row under Current Admins."], ["Người bỏ phiếu là các quản trị viên có quyền quản lý đội ngũ, trừ chính tài khoản bị xét (không tự bỏ phiếu cho mình). Cần ít nhất 2 người bỏ phiếu; admin mới phải được cấp quyền quản lý đội ngũ trước.", "Voters are the admins who have team-management access, except the account in question (it does not vote on itself). At least 2 voters are needed; a new admin must be granted team-management access first."], ["Cần đa số tuyệt đối của người bỏ phiếu (hơn một nửa) đồng ý. Người mở cuộc bỏ phiếu tính là một phiếu đồng ý; mỗi người một phiếu và không đổi được.", "A strict majority of the voters (more than half) must approve. The person who opens the vote counts as one yes; each voter has one ballot and cannot change it."], ["Cuộc bỏ phiếu hết hạn sau 72 giờ; người mở có thể huỷ. Nếu số quản trị viên giảm xuống dưới 3 trước khi có kết quả thì việc gỡ bị huỷ.", "A vote expires after 72 hours; its opener can cancel it. If the admin count drops below 3 before it is decided, the removal is cancelled."], ["Thông qua: quyền được gỡ ngay. Bị từ chối hoặc không còn đủ phiếu đồng ý: không có gì thay đổi.", "If it passes the removal happens immediately. If it is rejected or can no longer reach a majority, nothing changes."]]),
            .tip("Cuộc bỏ phiếu đang mở xuất hiện trong \"Open Votes\" của Đội ngũ quản trị, và bạn nhận thông báo khi có cuộc bỏ phiếu mới hoặc có kết quả.", "Open votes appear under \"Open Votes\" in Admin Team, and you get a notification when a vote opens or is decided."),
        ]),
        HelpSection(id: "test", vi: "Tài khoản thử nghiệm", en: "Test accounts", blocks: [
            .ol([["Review & Moderation > \"Test accounts\"; tìm theo email hoặc tên hiển thị.", "Review & Moderation > \"Test accounts\"; search by email or display name."], ["Nhập số điện thoại quốc tế (+84…), bật \"Waive SMS OTP (test account)\" và \"Save\".", "Enter an international phone (+84…), switch on \"Waive SMS OTP (test account)\" and \"Save\"."], ["Có thể đặt ngày sinh nếu tài khoản chưa có; ngày sinh sẵn có không bao giờ bị ghi đè.", "You can set a date of birth if none exists; an existing one is never overwritten."]]),
            .tip("Số điện thoại vẫn KHÔNG được xác minh và không có SMS nào được gửi. Bạn không thể áp dụng cho chính mình.", "The phone stays NOT verified and no SMS is sent. You cannot apply this to your own account."),
        ]),
        HelpSection(id: "reports", vi: "Số liệu & báo cáo", en: "Metrics & reports", blocks: [
            .p("Ngoài số liệu thường, admin thấy: sự kiện chờ duyệt, tranh chấp chưa giải quyết, tuổi trung bình tồn đọng, sự kiện và đặt chỗ mới toàn nền tảng. Xuất CSV/JSON/PDF.", "Besides the usual metrics, admins see: events pending review, unresolved disputes, average backlog age, new events and bookings platform-wide. Export CSV/JSON/PDF."),
        ]),
        ]
    )

    static let faq = HelpDoc(
        vi: "Hỏi & Đáp", en: "Q&A",
        introVi: "Câu hỏi thường gặp. Dùng ô tìm kiếm để lọc nhanh.", introEn: "Frequently asked questions. Use the search box to filter.",
        adminOnly: false,
        sections: [
        HelpSection(id: "account", vi: "Tài khoản & đăng nhập", en: "Account & login", blocks: [
            .q("Tôi có xem sự kiện mà không cần đăng nhập được không?", "Can I browse events without signing in?", "Không. banbe cần đăng nhập để dùng; bạn sẽ được đưa tới trang đăng nhập.", "No. banbe needs you to be signed in; you will be taken to the login page."),
            .q("Tại sao phải xác minh số điện thoại và ngày sinh?", "Why do I have to verify my phone and date of birth?", "Để bảo vệ tài khoản và vì mỗi vé gắn với tên và ngày sinh của người tham dự. Ngày sinh chỉ hiển thị cho host khi soát vé.", "To protect accounts, and because each ticket is tied to the attendee's name and date of birth. Hosts only see it at check-in."),
            .q("Tôi không nhận được mã SMS / email.", "I did not get the SMS / email code.", "Đợi 60 giây rồi nhấn gửi lại, kiểm tra mã quốc gia của số điện thoại, và kiểm tra thư rác với email.", "Wait 60 seconds and resend, check the country code on your number, and check your spam folder for emails."),
            .q("Tôi quên mật khẩu.", "I forgot my password.", "Ở trang đăng nhập nhấn \"Forgot password?\" để nhận email đặt lại mật khẩu (8+ ký tự).", "On the login page tap \"Forgot password?\" to get a reset email (8+ characters)."),
            .q("Làm sao đổi ngôn ngữ hoặc giao diện sáng/tối?", "How do I change language or light/dark mode?", "Account > Settings > \"Language & Appearance\".", "Account > Settings > \"Language & Appearance\"."),
            .q("Làm sao xóa tài khoản?", "How do I delete my account?", "Account > Settings > \"Delete Account\". Bạn cần xác minh bằng mã email. Không thể hoàn tác, và không xóa được khi còn sự kiện đang mở.", "Account > Settings > \"Delete Account\". You verify with an emailed code. It cannot be undone, and it is blocked while you own an open event."),
            .q("Tôi muốn xin bản sao dữ liệu của mình.", "I want a copy of my data.", "Hiện chưa có chức năng tự xuất; hãy liên hệ qua email nêu trong Điều khoản.", "There is no self-serve export yet; contact the email given in the Terms."),
            .q("Chip \"For You\" là gì và vì sao nó lấp lánh?", "What is the \"For You\" chip and why does it sparkle?", "Đó là lối tắt tới các sự kiện khớp câu trả lời sở thích của bạn. Nó lấp lánh vài giây khi có sự kiện mới khớp, rồi giữ nhãn \"New\" nhỏ cho đến khi bạn mở. Không phải sự kiện mới nào cũng báo, và nó không ảnh hưởng đến việc bạn có đủ điều kiện đặt chỗ hay không.", "It is a shortcut to events matching your preference answers. It sparkles for a few seconds when a new matching event appears, then keeps a small \"New\" label until you open it. Not every new event triggers it, and it does not affect whether you are eligible to reserve."),
            .q("Làm sao bật móc khoá trên hồ sơ?", "How do I turn on a keychain on my profile?", "Mở hồ sơ của bạn, nhấn \"Edit charm\", bật công tắc, chọn mẫu/góc/kích cỡ, xem trước rồi Save. Mặc định móc khoá tắt.", "Open your profile, tap \"Edit charm\", switch it on, pick a design/corner/size, preview and Save. The keychain is off by default."),
            .q("Tôi dùng ảnh riêng cho móc khoá được không?", "Can I use my own image for the keychain?", "Được: chọn PNG hoặc WebP nền trong suốt từ máy (tối đa 512 px, 256 KB, tối đa 3 ảnh). banbe thu nhỏ ảnh và xoá siêu dữ liệu; SVG/HTML/GIF bị từ chối. Hãy chỉ dùng ảnh bạn có quyền sử dụng.", "Yes: choose a transparent PNG or WebP from your device (up to 512 px, 256 KB, at most 3 images). banbe resizes it and strips metadata; SVG/HTML/GIF are rejected. Only use images you have the right to use."),
            .q("Móc khoá có làm máy hao pin hoặc giật không? Tôi muốn tắt chuyển động.", "Does the keychain drain battery or lag? I want no motion.", "Móc khoá chỉ chuyển động khi bạn kéo hoặc lắc, rồi dừng hẳn; cảm biến chỉ chạy khi nó đang hiện trên màn hình. Tắt \"Motion\" trong Edit charm hoặc bật \"Giảm chuyển động\" của thiết bị để nó đứng yên.", "It only moves when you drag or shake it, then stops completely; sensors only run while it is on screen. Turn off \"Motion\" in Edit charm or enable the device Reduce Motion setting to keep it still."),
        ]),
        HelpSection(id: "booking", vi: "Đặt chỗ & vé", en: "Booking & tickets", blocks: [
            .q("Giữ chỗ kéo dài bao lâu?", "How long is a seat held?", "Với sự kiện có phí, ghế được giữ 30 phút. Khi bạn xác nhận đã chuyển tiền, đồng hồ dừng và ghế được khóa cho đến khi host xác nhận.", "For paid events a seat is held for 30 minutes. Once you confirm you have transferred, the clock stops and the seat is locked until the host confirms."),
            .q("Hết giờ giữ chỗ thì sao?", "What if the hold expires?", "Ghế được nhả ra. Nhấn \"Reserve again\" nếu còn chỗ.", "The seat is released. Tap \"Reserve again\" if there is still room."),
            .q("Tôi đặt được bao nhiêu vé?", "How many tickets can I book?", "Tối đa 6 vé mỗi lần đặt, và mỗi sự kiện chỉ một đặt chỗ đang hiệu lực. Mỗi vé cần tên và ngày sinh của người tham dự.", "Up to 6 tickets per booking, with one live booking per event. Each ticket needs the attendee's name and date of birth."),
            .q("Tại sao tôi chưa thấy mã QR?", "Why can't I see my QR code?", "Mã QR chỉ được cấp sau khi host xác nhận đã nhận tiền (hoặc ngay lập tức với sự kiện miễn phí).", "The QR is issued only after the host confirms receipt (or immediately for free events)."),
            .q("Sự kiện hết chỗ, tôi làm gì?", "The event is sold out. What can I do?", "Nhắn tin cho host để hỏi danh sách chờ (\"Sold out ▪︎ message for waitlist\").", "Message the host to ask about a waitlist (\"Sold out ▪︎ message for waitlist\")."),
            .q("Có thêm vé vào Apple Wallet được không?", "Can I add a ticket to Apple Wallet?", "Chưa. Tính năng này chưa được bật; hãy dùng mã QR hoặc PDF.", "Not yet. It is not switched on; use the QR or PDF."),
            .q("Tôi tặng vé cho bạn bè thế nào?", "How do I give a ticket to a friend?", "Dùng \"Give a ticket to a friend\" trên vé, rồi gửi PDF; người nhận nhập mã bằng \"Import a gift or group ticket\". Không dùng được với đặt chỗ có tên người tham dự riêng.", "Use \"Give a ticket to a friend\" on the ticket and send the PDF; the recipient enters the code via \"Import a gift or group ticket\". Not available for bookings with named attendees."),
            .q("Đặt chỗ có tên người tham dự thì vào cửa thế nào?", "How does entry work with named attendees?", "Mỗi người quét mã QR của chính mình; mã của cả đơn đặt chỗ không được chấp nhận.", "Each person scans their own QR; a whole-booking code is not accepted."),
        ]),
        HelpSection(id: "payments", vi: "Thanh toán", en: "Payments", blocks: [
            .q("banbe có thu tiền không?", "Does banbe collect payments?", "Không. Bạn chuyển khoản trực tiếp cho host; banbe chỉ hiển thị thông tin nhận tiền và ghi nhận trạng thái.", "No. You pay the host directly; banbe only shows the payment details and records status."),
            .q("Tôi đã chuyển tiền nhưng host chưa xác nhận.", "I paid but the host has not confirmed.", "Dùng \"Remind the organizer to confirm\" (tối đa 2 lần), nhắn cho host bằng \"Message host\", rồi \"Raise a dispute\" nếu vẫn không có kết quả.", "Use \"Remind the organizer to confirm\" (max 2 times), message them with \"Message host\", then \"Raise a dispute\" if it is still stuck."),
            .q("Host nói không tìm thấy khoản chuyển của tôi.", "The host says they can't find my payment.", "Gửi lại Transaction ID và ảnh biên lai trong chat. Nếu host chuyển lên banbe, một chat tranh chấp mở ra và quản trị viên sẽ quyết định.", "Resend the Transaction ID and receipt image in chat. If the host escalates to banbe, a dispute chat opens and an admin decides."),
            .q("Tôi lấy hóa đơn / biên lai ở đâu?", "Where do I get an invoice / receipt?", "Trên vé, \"View Receipt\"; nếu chưa có, \"Request Receipt\". Hóa đơn do host tải lên. Bạn có thể bật tự động email bản sao trong Settings.", "On the ticket, \"View Receipt\"; if there is none, \"Request Receipt\". Invoices are uploaded by the host. You can turn on automatic email copies in Settings."),
            .q("Tôi chuyển nhầm nội dung chuyển khoản.", "I used the wrong transfer reference.", "Nhắn host kèm Transaction ID và ảnh biên lai để họ đối chiếu thủ công.", "Message the host with the Transaction ID and receipt image so they can reconcile manually."),
        ]),
        HelpSection(id: "refunds", vi: "Hoàn tiền & tranh chấp", en: "Refunds & disputes", blocks: [
            .q("Tôi được hoàn tiền khi nào?", "When do I get a refund?", "Khi host hủy sự kiện hoặc hủy đặt chỗ của bạn. Còn lại tùy điều khoản hoàn tiền host đăng trên trang sự kiện; banbe không hoàn tiền thay host.", "When the host cancels the event or your booking. Otherwise it depends on the refund terms the host posted on the event page; banbe does not refund on a host's behalf."),
            .q("Tôi cần làm gì để nhận hoàn tiền?", "What do I need to do to get refunded?", "Thêm tài khoản nhận ở Refund Accounts và chọn \"Choose a refund destination\" cho yêu cầu hoàn tiền của bạn.", "Add a receiving account in Refund Accounts and use \"Choose a refund destination\" on your refund claim."),
            .q("Bao lâu thì tiền về?", "How long until the money arrives?", "Host cam kết chuyển trong 3 ngày làm việc kể từ lúc hủy. Thời gian tiền về phụ thuộc ngân hàng.", "The host owes the transfer within 3 business days of cancellation. Arrival time depends on your bank."),
            .q("Nếu tôi quên xác nhận đã nhận tiền?", "What if I forget to confirm receipt?", "Sau 7 ngày kể từ khi host đánh dấu đã gửi, hệ thống tự ghi nhận đã nhận. Nếu chưa nhận được, hãy khiếu nại trước đó.", "After 7 days from the host marking it sent, it is auto-confirmed. If you have not received it, dispute before then."),
            .q("Tôi có thể gửi ảnh/tệp trong khiếu nại không?", "Can I send photos or files in a dispute?", "Có: JPG, PNG, WebP hoặc PDF, tối đa 20 MB. Tin nhắn không xóa hoặc sửa được.", "Yes: JPG, PNG, WebP or PDF, up to 20 MB. Messages cannot be edited or deleted."),
            .q("Dữ liệu khiếu nại được giữ bao lâu?", "How long is dispute data kept?", "Dữ liệu tranh chấp hoàn tiền bị xóa 7 ngày sau khi đóng. Hãy tải transcript nếu bạn cần.", "Refund-dispute data is purged 7 days after closing. Download the transcript if you need it."),
        ]),
        HelpSection(id: "messages", vi: "Tin nhắn & thông báo", en: "Messages & notifications", blocks: [
            .q("Tại sao cuộc trò chuyện chưa hiện trong Messages?", "Why isn't my chat in Messages yet?", "Cuộc trò chuyện chỉ xuất hiện sau khi bạn gửi tin đầu tiên.", "A chat only appears after you send your first message."),
            .q("Xóa cuộc trò chuyện có ảnh hưởng người kia không?", "Does deleting a chat affect the other person?", "Không; chỉ ẩn với bạn. Nó hiện lại nếu họ nhắn tiếp.", "No; it is hidden for you only and returns if they message you again."),
            .q("Tôi không nhận thông báo đẩy.", "I get no push notifications.", "Thông báo đẩy chưa bật. Hãy xem tab Notifications và email.", "Push notifications are not enabled yet. Check the Notifications tab and your email."),
        ]),
        HelpSection(id: "hosting", vi: "Dành cho host", en: "For hosts", blocks: [
            .q("Làm sao trở thành host?", "How do I become a host?", "Bật \"Organizer mode\" trong Account rồi tạo sự kiện đầu tiên. Host phải từ 18 tuổi.", "Switch on \"Organizer mode\" in Account and create your first event. Hosts must be 18+."),
            .q("Sự kiện của tôi được duyệt mất bao lâu?", "How long does event approval take?", "Thời gian không được cam kết. Bạn có thể nhắc quản trị viên tối đa 2 lần mỗi sự kiện; hãy gửi sớm.", "There is no guaranteed time. You can remind admins up to 2 times per event; submit early."),
            .q("Sự kiện bị từ chối thì sao?", "My event was rejected.", "Đọc lý do, chỉnh sửa rồi \"Fix & resubmit\".", "Read the reason, edit it and tap \"Fix & resubmit\"."),
            .q("banbe có tự xác nhận thanh toán nếu tôi không phản hồi không?", "Does banbe confirm payments for me if I do not respond?", "Không. Ghế của khách bị khóa cho đến khi bạn xác nhận hoặc từ chối; hãy phản hồi trong khoảng 1 giờ.", "No. The guest's seat stays locked until you confirm or decline; aim to respond within about an hour."),
            .q("Tôi hủy sự kiện thế nào và khách được báo ra sao?", "How do I cancel an event and tell guests?", "Attendance > \"Cancel event\", chọn mẫu xin lỗi. Email nháp cho từng khách mở trong ứng dụng email của bạn; bạn tự gửi.", "Attendance > \"Cancel event\", pick an apology template. A draft email per guest opens in your own mail app; you send them yourself."),
            .q("Tôi nhập sự kiện từ Excel được không?", "Can I import an event from Excel?", "Được, một sự kiện mỗi tệp (.xlsx hoặc .zip có ảnh). Tệp chỉ điền sẵn biểu mẫu; bạn vẫn phải xem lại và gửi.", "Yes, one event per file (.xlsx or a .zip with photos). It only pre-fills the form; you still review and submit."),
            .q("Khách không đến thì sao?", "What about no-shows?", "Không có tiền phạt tự động. Chỉ những khách không đến mà không hủy mới có thể bị đánh dấu.", "There is no automatic penalty. Only guests who do not come without cancelling may be marked."),
            .q("Tôi nhận biên lai cho khách thế nào?", "How do I provide receipts to guests?", "Trong Attendance, đánh dấu khách đã trả rồi \"Upload receipt\" bằng tệp của bạn.", "In Attendance, mark the guest paid, then \"Upload receipt\" with your own file."),
        ]),
        HelpSection(id: "trust", vi: "An toàn & quyền riêng tư", en: "Safety & privacy", blocks: [
            .q("Điều khoản và quyền riêng tư ở đâu?", "Where are the Terms and Privacy Notice?", "Account > Help & Legal > Terms.", "Account > Help & Legal > Terms."),
            .q("Ai xem được ngày sinh của tôi?", "Who can see my date of birth?", "Host chỉ thấy khi soát vé; việc tra cứu bị giới hạn và có ghi nhật ký.", "Hosts only see it at check-in; lookups are rate-limited and logged."),
            .q("Người dùng được tính tuổi tối thiểu bao nhiêu?", "What is the minimum age?", "Theo Điều khoản: 16+ để dùng, 18+ để làm host.", "Per the Terms: 16+ to use banbe, 18+ to host."),
            .q("Tôi nên báo cáo vấn đề ở đâu?", "Where do I report a problem?", "Dùng email liên hệ trong Điều khoản, hoặc tranh chấp trong ứng dụng nếu liên quan đến thanh toán/hoàn tiền.", "Use the contact email in the Terms, or an in-app dispute if it concerns a payment/refund."),
        ]),
        ]
    )

    static func guide(_ key: String?) -> HelpDoc? {
        switch key {
        case "personal": return personal
        case "host": return host
        case "admin": return admin
        default: return nil
        }
    }
}
